'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let topics=[],filter='todos',query='',states,municipalities,selectedState=null;
const sidebar=$('#sidebar'),scrim=$('#sidebarScrim');
function closeSidebar(){document.body.classList.remove('menu-open');sidebar.classList.remove('open');scrim.classList.remove('open');$('#sidebarToggle').setAttribute('aria-expanded','false')}
$('#sidebarToggle').onclick=()=>{document.body.classList.add('menu-open');sidebar.classList.add('open');scrim.classList.add('open');$('#sidebarToggle').setAttribute('aria-expanded','true');$('#sidebarClose').focus()};$('#sidebarClose').onclick=closeSidebar;scrim.onclick=closeSidebar;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebar.classList.contains('open')){closeSidebar();$('#sidebarToggle').focus()}if(e.key==='Tab'&&sidebar.classList.contains('open')){const list=[...sidebar.querySelectorAll('a,button')];const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function projector(){document.body.classList.toggle('projector-mode');const on=document.body.classList.contains('projector-mode');$('#projectorBtn').setAttribute('aria-pressed',String(on));$('#projectorBtn span').textContent=on?'Salir del proyector':'Proyector';$('#projectorBtn').setAttribute('aria-label',on?'Salir del modo proyector':'Activar modo proyector');$('#projectorBtn').title=on?'Salir del modo proyector':'Activar modo proyector';$('#sidebarProjector').textContent=on?'Desactivar proyector':'Activar proyector';closeSidebar();window.dispatchEvent(new Event('atlas-projector-change'))}
$('.skip-link').onclick=e=>{e.preventDefault();$('#mainContent').focus();$('#mainContent').scrollIntoView({block:'start'})};
$('#projectorBtn').onclick=projector;$('#sidebarProjector').onclick=projector;
const pairList=a=>a.map(([a,b])=>`<li><strong>${esc(a)}</strong><p>${esc(b)}</p></li>`).join('');
const sourceList=t=>`<ol class="sources">${t.sources.map(([n,u,k])=>`<li><a href="${esc(u)}" target="_blank" rel="noopener">${esc(n)} ↗</a><small>${esc(k)}</small></li>`).join('')}</ol>`;
const download=t=>`<a class="btn btn-primary" href="downloads/${t.id}.pdf" download>↓ Guía docente PDF</a>`;
function cards(){const visible=topics.filter(t=>(filter==='todos'||t.scope===filter||norm(t.level).includes(filter))&&norm(JSON.stringify(t)).includes(norm(query)));$('#topicGrid').innerHTML=visible.map(t=>`<article class="topic-card"><div class="topic-number">${String(topics.indexOf(t)+1).padStart(2,'0')}</div><div><span class="topic-tag">${esc(t.era)}</span><h3>${esc(t.title)}</h3><p>${esc(t.summary)}</p><div class="topic-meta"><span>${t.duration} min</span><span>PDF</span><span>Fuentes</span></div><a class="card-link" href="#ruta/${t.id}">Abrir ruta →</a></div></article>`).join('');$('#noResults').hidden=visible.length>0;$('#noResults').textContent='No hay rutas con esos filtros. Prueba otro término o selecciona Ver todos.'}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});cards()});
$('#clearFilter').onclick=()=>{query='';filter='todos';$('#searchInput').value='';$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter==='todos');x.setAttribute('aria-pressed',String(x.dataset.filter==='todos'))});cards()};
function search(){query=$('#searchInput').value.trim();cards();location.hash='temas'}$('#searchBtn').onclick=search;$('#searchInput').onkeydown=e=>{if(e.key==='Enter')search()};
function topicView(t){$('#ruta').innerHTML=`<a class="text-link" href="#temas">← Todas las rutas</a><header class="route-heading"><p class="eyebrow">${esc(t.era)} · ${t.duration} MINUTOS</p><h1>${esc(t.title)}</h1><p class="route-question">${esc(t.question)}</p><p>${esc(t.level)}</p><div class="actions">${download(t)}<button class="ghost-btn" id="printRoute">Imprimir ficha</button></div></header><nav class="route-tabs" aria-label="Contenido de la ruta">${['Clase','Profundizar','Actividad','Juego','Fuentes'].map((n,i)=>`<button data-panel="${i}" aria-pressed="${i===0}">${n}</button>`).join('')}</nav><div class="route-panel" data-view="0"><div class="callout"><strong>Objetivo de aprendizaje</strong><p>${esc(t.objective)}</p></div><h2>Para explicar en clase</h2><p class="lead">${esc(t.summary)}</p>${t.classroom.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="detail-grid"><article class="paper"><h2>Personajes y protagonistas</h2><ul>${pairList(t.people)}</ul></article><article class="paper"><h2>Fechas clave</h2><ul>${pairList(t.dates)}</ul></article></div><article class="paper"><h2>Lugares de esta historia</h2><p>Ubicaciones actuales de referencia; no representan fronteras de la época.</p><div class="place-list">${t.places.map(p=>`<a href="https://www.openstreetmap.org/?mlat=${p.lat}&mlon=${p.lon}#map=11/${p.lat}/${p.lon}" target="_blank" rel="noopener"><strong>${esc(p.name)} ↗</strong><span>${esc(p.note)}</span></a>`).join('')}</div>${t.scope==='mexico'?'<a href="#mapa" class="text-link">Explorar el mapa de México →</a>':''}</article><div class="callout"><strong>Una pregunta curiosa</strong><p>${esc(t.curiosity)}</p></div></div><div class="route-panel" data-view="1" hidden><h2>Una lectura más profunda</h2>${t.deep.map(p=>`<p>${esc(p)}</p>`).join('')}<h2>¿Qué sabemos y cómo lo sabemos?</h2><div class="evidence-grid">${t.evidence.map(([n,d])=>`<article class="paper"><span class="topic-tag">${esc(n)}</span><p>${esc(d)}</p></article>`).join('')}</div><p class="muted">Síntesis educativa basada en las referencias de esta ficha. Las interpretaciones pueden discutirse con evidencia.</p>${sourceList(t)}</div><div class="route-panel" data-view="2" hidden><h2>Una clase de ${t.duration} minutos</h2><ol class="steps">${t.activity.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="detail-grid"><article class="paper"><h3>Evaluación formativa</h3><p>${esc(t.assessment)}</p></article><article class="paper"><h3>Adaptación por nivel</h3><p>${esc(t.adaptation)}</p></article></div>${download(t)}</div><div class="route-panel" data-view="3" hidden><h2>Comprueba y conversa</h2><div id="routeQuiz"></div></div><div class="route-panel" data-view="4" hidden><h2>Fuentes para seguir investigando</h2>${sourceList(t)}<p>Consulta editorial: septiembre de 2026. Las fechas aproximadas se indican con “c.”. Los relatos tradicionales se presentan como expresiones culturales, no como hechos comprobados.</p></div>`;
$('#printRoute').onclick=()=>window.print();$$('[data-panel]').forEach(b=>b.onclick=()=>{$$('[data-panel]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('[data-view]').forEach(x=>x.hidden=x.dataset.view!==b.dataset.panel)});quiz($('#routeQuiz'),t.quiz);window.AtlasProjection?.install(t);if(t.id==='mesoamerica')window.AtlasMesoamerica?.install(t);window.AtlasLearning?.installRoute(t)}
function quiz(host,questions){let i=0,score=0;function draw(){if(i===questions.length){host.innerHTML=`<div class="callout"><h3>Reto completado</h3><p>${score} de ${questions.length} respuestas correctas.</p><p>Explica una respuesta usando una evidencia de la ruta.</p><button class="btn btn-primary">Volver a jugar</button></div>`;host.querySelector('button').onclick=()=>{i=0;score=0;draw()};return}const [q,opts,correct,why]=questions[i];host.innerHTML=`<p class="eyebrow">PREGUNTA ${i+1} / ${questions.length} · ${score} ACIERTOS</p><h3>${esc(q)}</h3><div class="quiz-options">${opts.map((x,j)=>`<button data-option="${j}">${esc(x)}</button>`).join('')}</div><p class="feedback" role="status"></p><button class="ghost-btn next" disabled>Siguiente →</button>`;host.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{let ok=+b.dataset.option===correct;if(ok)score++;host.querySelectorAll('[data-option]').forEach(x=>{x.disabled=true;x.classList.toggle('correct',+x.dataset.option===correct)});host.querySelector('.feedback').textContent=(ok?'Correcto. ':'Revisemos. ')+why;host.querySelector('.next').disabled=false});host.querySelector('.next').onclick=()=>{i++;draw()}}draw()}
function games(){const selected=$('#gameTopic').value;const t=topics.find(t=>t.id===selected);window.AtlasLearning?.games(t);quiz($('#globalQuiz'),t.quiz);const order=t.dates.map((x,i)=>({x,i})).reverse();function redraw(){const h=$('#ordering');h.innerHTML=`<h3>Ordena la historia</h3><p>Coloca los acontecimientos del más antiguo al más reciente.</p><ol class="order-list">${order.map((v,i)=>`<li><span>${esc(v.x[1])}</span><div><button data-up="${i}" ${i===0?'disabled':''} aria-label="Subir ${esc(v.x[1])}">↑</button><button data-down="${i}" ${i===order.length-1?'disabled':''} aria-label="Bajar ${esc(v.x[1])}">↓</button></div></li>`).join('')}</ol><button id="checkOrder" class="btn btn-secondary">Comprobar orden</button><p id="orderFeedback" role="status"></p>`;h.querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const from=Number(b.dataset.up??b.dataset.down),to=from+(b.hasAttribute('data-up')?-1:1);[order[from],order[to]]=[order[to],order[from]];redraw()});$('#checkOrder').onclick=()=>{$('#orderFeedback').textContent=order.every((v,i)=>v.i===i)?'¡Orden correcto! '+t.dates.map(x=>x.join(': ')).join(' · '):'Todavía hay acontecimientos fuera de orden. Consulta las fechas de la ruta y vuelve a intentarlo.'}}redraw();quiz($('#evidenceQuiz'),t.evidence.map(([label,d])=>[d,t.evidence.map(x=>x[0]),t.evidence.findIndex(x=>x[0]===label),'Esta afirmación se presenta como '+label.toLowerCase()+'. Consulta la lectura profunda y sus fuentes.']))}
const project=([lon,lat])=>[(lon+118.5)*23,(33.5-lat)*25];
function path(g){const polys=g.type==='Polygon'?[g.coordinates]:g.coordinates;return polys.map(p=>p.map(r=>r.map((c,i)=>{const [x,y]=project(c);return`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`}).join('')+'Z').join('')).join('')}
function stateName(f){return f.properties.state_code===9?'Ciudad de México':f.properties.state_name}
async function mapInit(){try{states=await fetch('data/states.geojson').then(r=>r.json());$('#stateSelect').innerHTML='<option value="">Todo México</option>'+states.features.slice().sort((a,b)=>stateName(a).localeCompare(stateName(b),'es')).map(f=>`<option value="${f.properties.state_code}">${esc(stateName(f))}</option>`).join('');$('#stateSelect').onchange=()=>{selectedState=$('#stateSelect').value;renderMap();localSearch()};$('#localSearch').oninput=localSearch;renderMap();municipalities=await fetch('data/municipalities.geojson').then(r=>r.json());localSearch()}catch(e){$('#mapResults').textContent='No se pudo cargar la cartografía. Recarga la página para volver a intentarlo.'}}
function renderMap(){const target=states.features.find(f=>String(f.properties.state_code)===String(selectedState));let view='0 0 750 500';if(target){const coords=target.geometry.type==='Polygon'?target.geometry.coordinates.flat():target.geometry.coordinates.flat(2);const pts=coords.map(project),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);view=`${Math.min(...xs)-8} ${Math.min(...ys)-8} ${Math.max(...xs)-Math.min(...xs)+16} ${Math.max(...ys)-Math.min(...ys)+16}`}
$('#geoMap').setAttribute('viewBox',view);$('#geoMap').innerHTML=`<title>Estados de México y sitios de las rutas</title>${states.features.map(f=>`<path d="${path(f.geometry)}" data-state="${f.properties.state_code}" class="state ${String(f.properties.state_code)===String(selectedState)?'selected':''}"><title>${esc(stateName(f))}</title></path>`).join('')}${topics.filter(t=>t.scope==='mexico').flatMap(t=>t.places.map(p=>{const [x,y]=project([p.lon,p.lat]);return`<a href="#ruta/${t.id}" aria-label="${esc(p.name)}: ${esc(t.title)}"><circle cx="${x}" cy="${y}" r="${target?1.1:3.5}" class="event-dot"><title>${esc(p.name)} · ${esc(t.title)}</title></circle></a>`})).join('')}`;$$('[data-state]').forEach(p=>p.onclick=()=>{selectedState=p.dataset.state;$('#stateSelect').value=selectedState;renderMap();localSearch()})}
function localSearch(){if(!municipalities){$('#mapResults').textContent='Cargando catálogo municipal…';return}const q=norm($('#localSearch').value);const found=municipalities.features.filter(f=>(!selectedState||String(f.properties.state_code)===String(selectedState))&&norm(f.properties.mun_name).includes(q));$('#mapResults').innerHTML=`<p>${found.length} municipios en el catálogo de referencia${found.length>30?' · mostrando los primeros 30':''}.</p><div class="municipal-list">${found.slice(0,30).map(f=>`<button data-mun="${f.properties.state_code}-${f.properties.mun_code}">${esc(f.properties.mun_name)}<small>${esc(stateName(states.features.find(s=>s.properties.state_code===f.properties.state_code)))}</small></button>`).join('')}</div>${found.length?'':'<p>Sin coincidencias. Prueba el municipio al que pertenece tu comunidad o consulta el archivo municipal. Este catálogo histórico no incluye todas las localidades ni cambios recientes.</p>'}`;$$('[data-mun]').forEach(b=>b.onclick=()=>{const f=found.find(f=>`${f.properties.state_code}-${f.properties.mun_code}`===b.dataset.mun);const n=f.properties.mun_name;const matching=topics.filter(t=>t.places.some(p=>norm(p.municipality)===norm(n)));$('#localDetail').innerHTML=`<p class="eyebrow">HISTORIA LOCAL</p><h3>${esc(n)}</h3>${matching.length?matching.map(t=>`<p><a href="#ruta/${t.id}">${esc(t.title)} →</a></p>`).join(''):'<p>Sin ficha histórica revisada en esta edición. El nombre en el mapa no implica que exista una monografía disponible.</p>'}<h4>Investiga tu comunidad</h4><ol><li>Elige un edificio, una fiesta o un cambio en el territorio.</li><li>Registra autor, fecha y procedencia de una fotografía o documento.</li><li>Contrasta el testimonio oral con otra fuente. Separa recuerdos, tradiciones y hechos documentados.</li></ol><a href="https://memoricamexico.gob.mx/" target="_blank" rel="noopener">Consultar Memórica ↗</a><p><a href="https://www.inegi.org.mx/app/areasgeograficas/" target="_blank" rel="noopener">Verificar localidad en INEGI ↗</a></p>`;const old=$('#municipalBoundary');if(old)old.remove();$('#geoMap').insertAdjacentHTML('beforeend',`<path id="municipalBoundary" d="${path(f.geometry)}"><title>${esc(n)}</title></path>`);$('#localDetail').scrollIntoView({behavior:'smooth',block:'nearest'})})}
function navigate(){let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'explorar')}catch{hash='explorar'};const id=hash.startsWith('ciencia/')?'ciencia':hash.startsWith('laboratorio/')?'laboratorio':hash.startsWith('retos/')?'retos':hash.startsWith('ruta/')?'ruta':hash.startsWith('patrimonio/')?'patrimonio':hash.startsWith('historietas/')?'historietas':hash==='inicio'?'explorar':hash;const section=document.getElementById(id);$$('main > section').forEach(s=>s.hidden=s!==section);if(id==='ruta'){const t=topics.find(x=>x.id===hash.split('/')[1]);if(t)topicView(t);else{$('#ruta').innerHTML='<h1>Ruta no encontrada</h1><a href="#temas">Volver a las rutas</a>'}}if(!section){$('#explorar').hidden=false}$$('.side-link').forEach(a=>{const active=(a.getAttribute('href')||'').split('/')[0]==='#'+id||(id==='ruta'&&a.getAttribute('href')==='#temas');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});closeSidebar();window.scrollTo(0,0);document.title=(id==='ruta'?topics.find(t=>t.id===hash.split('/')[1])?.title:section?.querySelector('h2,h1')?.textContent)||'Atlas';window.AtlasScience?.route(hash);window.AtlasInteractive?.route(hash)}
async function init(){try{const response=await fetch('data/topics.json');if(!response.ok)throw Error('topics');topics=await response.json();cards();$('#recursos .resource-grid').innerHTML=topics.map(t=>`<article class="paper"><span class="topic-tag">${t.duration} MIN · PDF</span><h3>${esc(t.title)}</h3><p>Explicación, secuencia didáctica, evaluación, preguntas con respuestas y fuentes.</p>${download(t)}</article>`).join('');$('#recursos .resource-grid').insertAdjacentHTML('beforeend','<article class="paper"><span class="topic-tag">8 DIAPOSITIVAS · PPTX</span><h3>México: historias que se conectan</h3><p>Presentación editable con preguntas de clase, fechas clave y fuentes en las notas.</p><a class="btn btn-primary" href="downloads/panorama-mexico.pptx" download>↓ PowerPoint editable</a></article>');$('#gameTopic').innerHTML=topics.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');$('#gameTopic').onchange=games;games();const year=d=>d.includes('Actualidad')?9999:d.includes('a. C.')?-Number(d.match(/\d+/)[0]):Number(d.match(/\d{4}/)[0]);const events=topics.filter(t=>t.scope==='mexico').flatMap(t=>t.dates.map(d=>({t,d}))).sort((a,b)=>year(a.d[0])-year(b.d[0]));const timelineNotes={mesoamerica:'Las sociedades mesoamericanas cambiaron durante siglos; esta fecha sirve como referencia para ubicar procesos, no como un inicio absoluto.',independencia:'La Independencia fue una secuencia de levantamientos, acuerdos y cambios políticos que afectó de manera distinta a cada región.',revolucion:'La Revolución reunió proyectos distintos y sus efectos —tierra, trabajo, educación y poder— se desarrollaron en varias etapas.',nacion:'La formación de México como nación implicó debates sobre territorio, ciudadanía, instituciones y formas de gobierno.'};$('#timelineEvents').innerHTML=events.map(({t,d})=>`<article class="paper timeline-card"><span class="topic-tag">${esc(d[0])}</span><h3>${esc(d[1])}</h3><p>${esc(timelineNotes[t.id]||'Este acontecimiento se relaciona con otros cambios de su época. Consulta la ruta para revisar personajes, lugares y fuentes.')}</p><a href="#ruta/${t.id}">${esc(t.title)} →</a></article>`).join('');window.addEventListener('hashchange',navigate);navigate();mapInit();window.AtlasLearning?.init(topics);window.AtlasScience?.init(topics);window.AtlasInteractive?.init()}catch(e){console.error('Atlas: no se pudieron cargar las rutas',e);$('#topicGrid').innerHTML='<p>No se pudieron cargar las rutas. Recarga la página para volver a intentarlo.</p>'}}init();
